final class BankImport{private$publicId,$tenantId,$bankAccountPublicId,$format,$fileName,$checksum,$rowCount,$importedCount,$skippedCount,$importedAt;public function __construct(string$publicId,TenantId$tenantId,string$account,string$format,string$fileName,string$checksum,int$rowCount,int$importedCount,int$skippedCount,int$importedAt){$publicId=trim($publicId);$account=trim($account);$format=strtolower(trim($format));$fileName=trim($fileName);$checksum=strtolower(trim($checksum));if($publicId===''||strlen($publicId)>64||$account===''||strlen($account)>64||preg_match('/^[a-z][a-z0-9_-]{1,31}$/D',$format)!==1||strlen($fileName)>255||preg_match('/^[a-f0-9]{64}$/D',$checksum)!==1){throw new \InvalidArgumentException('Bankimport bevat ongeldige identificatiegegevens.');}if($rowCount<0||$importedCount<0||$skippedCount<0||$importedCount+$skippedCount!==$rowCount||$importedAt<0){throw new \InvalidArgumentException('Bankimport bevat ongeldige aantallen of tijd.');}$this->publicId=$publicId;$this->tenantId=$tenantId;$this->bankAccountPublicId=$account;$this->format=$format;$this->fileName=$fileName;$this->checksum=$checksum;$this->rowCount=$rowCount;$this->importedCount=$importedCount;$this->skippedCount=$skippedCount;$this->importedAt=$importedAt;}public function getPublicId():string{return$this->publicId;}public function getTenantId():TenantId{return$this->tenantId;}public function getBankAccountPublicId():string{return$this->bankAccountPublicId;}public function getFormat():string{return$this->format;}public function getFileName():string{return$this->fileName;}public function getChecksum():string{return$this->checksum;}public function getRowCount():int{return$this->rowCount;}public function getImportedCount():int{return$this->importedCount;}public function getSkippedCount():int{return$this->skippedCount;}public function getImportedAt():int{return$this->importedAt;}}
